import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (name, tfm, pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))
changes = []
unchanged = []
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    proj, tfm, pkg = k
    if bv != av:
        changes.append((proj, tfm, pkg, bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append((proj, tfm, pkg, bv))

if changes:
    print('CHANGES:')
    print(f'{\"Project\":<16} {\"TFM\":<8} {\"Package\":<45} {\"Before\":<10} {\"After\":<10}')
    for c in changes:
        print(f'{c[0]:<16} {c[1]:<8} {c[2]:<45} {c[3]:<10} {c[4]:<10}')
else:
    print('No version changes detected.')

print()
print(f'Total unchanged: {len(unchanged)}, Total changed: {len(changes)}')
